import{t,catalogs,lang,translateError,languageMenu,bindLanguage}from'./i18n.js';
export function L(s){for(const key of Object.keys(catalogs.ko))if(catalogs.ko[key]===s)return t(key);const aliases={'추가':'added','누락':'removed','변경':'changed','A 값':'before','B 값':'after','예외 레코드':'exceptionRecords','추가 · B에만':'added','누락 · A에만':'removed','값 변경':'changed','동일':'same','원본 행(JSON)':'original','빈 키':'emptyKey','중복 키':'duplicateKey'};if(aliases[s])return t(aliases[s]);let m;if((m=s.match(/^A (\d+)행 · B (\d+)행/)))return t('ready',{a:m[1],b:m[2]});if((m=s.match(/^대조 완료. 중복 키 (\d+)종 제외. 예외 (\d+)레코드/)))return t('finished',{n:m[1],e:m[2]});if((m=s.match(/^키: (.*)$/s)))return t('keyMeta',{key:m[1]});if((m=s.match(/^· (\d+)셀$/)))return '· '+t('cells',{n:m[1]});return translateError({message:s});}
const set=(selector,key)=>{const el=document.querySelector(selector);if(el)el.textContent=t(key);};
document.title=t('title')+' · Table Diff';
set('.local','local');set('.eyebrow','eyebrow');document.querySelector('h1').innerHTML=t('headline')+'<br><em>'+t('accent')+'</em>';set('.intro>p:last-child','intro');set('h2 span','inputTitle');set('#example','example');set('label[for="a"]','baseline');set('label[for="b"]','newTable');
for(const select of document.querySelectorAll('#da,#db'))['auto','tab','comma','semi','pipe'].forEach((key,i)=>{select.options[i].textContent=t(key);});
for(const label of document.querySelectorAll('.file'))label.firstChild.textContent=t('file');
set('.workspace>.hint','limits');set('#prepare','read');set('label[for="key"]','key');document.querySelector('#trim').parentElement.lastChild.textContent=t('trim');set('#compare','compare');set('#results h2 span','results');set('#download','diffCsv');set('#exceptions','exceptionCsv');document.querySelector('#safe').parentElement.lastChild.textContent=t('safe');set('#results>.hint','safeNote');
const headings=document.querySelectorAll('#results h3');headings[0].firstChild.textContent=t('details')+' ';headings[1].textContent=t('exceptions');set('#results h3+.hint','duplicateNote');set('summary','rules');set('details p','ruleText');document.querySelector('details p:last-child').innerHTML=t('standardText')+': <a href="https://www.rfc-editor.org/rfc/rfc4180" target="_blank" rel="noreferrer">RFC 4180</a> · <a href="https://owasp.org/www-community/attacks/CSV_Injection" target="_blank" rel="noreferrer">OWASP CSV Injection</a>. '+t('delimiterText');set('footer span','privacy');document.querySelector('header').insertAdjacentHTML('beforeend',languageMenu());bindLanguage();
export const localDiffRows=rows=>rows.map((row,i)=>row.map((value,j)=>i===0||j===0?L(value):value));
export const localExceptionRows=rows=>rows.map((row,i)=>row.map((value,j)=>i===0||j===3?L(value):value));

document.querySelector('.workspace').setAttribute('aria-label',t('inputTitle'));for(const id of ['da','db'])document.getElementById(id).setAttribute('aria-label',id.slice(1).toUpperCase()+' · '+t('auto'));
